<script setup lang="ts">
import TaskAcceptance from '@/components/points/TaskAcceptance.vue'
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useProjectStore } from '@/stores/project'
import { listRequirements, createRequirement, updateRequirement, listTasks, saveTask, deleteTask, type Requirement, type Task, type TaskInput } from '@/api/requirements'
import { listPoints, type Point, type Platform } from '@/api/tracking'
import { listProjectMembers, type ProjectMember } from '@/api/projects'
const route = useRoute(), projects = useProjectStore()
const projectId = computed(() => Number(route.params.projectId))
const requirements = ref<Requirement[]>([]), tasks = ref<Task[]>([]), points = ref<Point[]>([]), members = ref<ProjectMember[]>([])
const selected = ref<Requirement | null>(null), error = ref(''), busy = ref(false), editing = ref(false), hasMore = ref(false), loadingMore = ref(false)
const input = ref({ title:'', goal:'', scenario:'', requirement_url:'', due_date:'' })
const task = ref<TaskInput>({ point_id:0, platform:'web', assignee_id:null, state:'PENDING' })
const platforms = computed(() => points.value.find(p => p.id === task.value.point_id)?.supported_platforms ?? [])
async function allPoints(project: number) { const first = await listPoints(project,{page:1,page_size:100}); const result = [...first.items]; for (let page=2; result.length < first.total; page++) { const next = await listPoints(project,{page,page_size:100}); if (!next.items.length) break; result.push(...next.items) } return result }
async function load() { error.value=''; selected.value=null; tasks.value=[]; requirements.value=[]; points.value=[]; members.value=[]; editing.value=false; hasMore.value=false; input.value={title:'',goal:'',scenario:'',requirement_url:'',due_date:''}; task.value={point_id:0,platform:'web',assignee_id:null,state:'PENDING'}; const id=projectId.value; try { const [rs, ps, ms] = await Promise.all([listRequirements(id),allPoints(id),listProjectMembers(id)]); if(id!==projectId.value) return; requirements.value=rs; hasMore.value=rs.length===100; points.value=ps; members.value=ms.filter(m=>m.is_active) } catch { if(id===projectId.value) error.value='加载需求或项目数据失败，请重试。' } }
watch(projectId, load, { immediate:true })
async function select(r: Requirement) { editing.value=false; selected.value=r; tasks.value=[]; error.value=''; const project=projectId.value; try { const result=await listTasks(project,r.id); if(project===projectId.value && selected.value?.id===r.id) tasks.value=result } catch { if(project===projectId.value && selected.value?.id===r.id) error.value='加载任务失败。' } }
async function create() { const project=projectId.value; busy.value=true; error.value=''; try { const {id}=await createRequirement(project,{...input.value}); const list=await listRequirements(project); if(projectId.value!==project)return; input.value={title:'',goal:'',scenario:'',requirement_url:'',due_date:''}; requirements.value=list; hasMore.value=list.length===100; const r=list.find(v=>v.id===id); if(r) await select(r) } catch { if(projectId.value===project)error.value='创建需求失败，请检查输入后重试。' } finally { busy.value=false } }
async function loadMore() { const id=projectId.value, last=requirements.value.at(-1); if(!last||loadingMore.value)return; loadingMore.value=true; try { const next=await listRequirements(id,last.id); if(id===projectId.value){requirements.value.push(...next);hasMore.value=next.length===100} } catch {if(id===projectId.value)error.value='加载更多需求失败。'} finally {loadingMore.value=false} }
function editRequirement() { if (!selected.value) return; const r=selected.value; input.value={ title:r.title, goal:r.goal, scenario:r.scenario, requirement_url:r.requirement_url, due_date:r.due_date }; editing.value=true }
async function saveRequirement() { if (!selected.value) return; const project=projectId.value, original=selected.value, fields={...input.value}; busy.value=true; error.value=''; try { await updateRequirement(project,original.id,fields); if(projectId.value!==project || selected.value?.id!==original.id)return; const changed={...original,...fields}; requirements.value=requirements.value.map(r=>r.id===original.id?changed:r); selected.value=changed; editing.value=false; input.value={title:'',goal:'',scenario:'',requirement_url:'',due_date:''} } catch { if(projectId.value===project)error.value='保存需求失败，请检查输入后重试。' } finally { busy.value=false } }
async function addTask() { if (!selected.value) return; const project=projectId.value,id=selected.value.id,fields={...task.value}; busy.value=true; error.value=''; try { await saveTask(project,id,fields); const result=await listTasks(project,id); if(projectId.value===project && selected.value?.id===id)tasks.value=result } catch { if(projectId.value===project && selected.value?.id===id)error.value='保存任务失败，请检查平台、负责人或是否重复。' } finally { busy.value=false } }
async function update(t: Task, state: TaskInput['state'], assigneeId: number | null = t.assignee_id) { if(!selected.value) return; const project=projectId.value,id=selected.value.id; error.value=''; try { await saveTask(project,id,{point_id:t.point_id,platform:t.platform,assignee_id:assigneeId,state},t.id); const result=await listTasks(project,id); if(projectId.value===project && selected.value?.id===id)tasks.value=result } catch { if(projectId.value===project && selected.value?.id===id)error.value='更新任务失败。' } }
async function removeTask(t: Task) { if(!selected.value || !window.confirm('确定删除该任务？已有验收记录的任务不能删除。')) return; const project=projectId.value, id=selected.value.id; try { await deleteTask(project,id,t.id); const result=await listTasks(project,id); if(projectId.value===project && selected.value?.id===id)tasks.value=result } catch { error.value='删除失败：已有验收记录的任务不能删除。' } }
function pointChanged() { task.value.platform=(platforms.value[0] || 'web') as Platform }
</script>
<template>
<section><header class="page-heading"><div><h1>埋点需求</h1><p>按需求组织点位，并跟踪各端接入进度。</p></div></header>
<p v-if="error" class="form-alert" role="alert">{{ error }} <button @click="load">重新加载</button></p>
<div class="detail-grid"><article class="detail-card"><h2>需求列表</h2><p v-if="!requirements.length">暂无需求</p><ul><li v-for="r in requirements" :key="r.id"><button class="text-link" @click="select(r)">{{ r.title }}</button></li></ul><button v-if="hasMore" type="button" :disabled="loadingMore" @click="loadMore">加载更多</button></article>
<article v-if="projects.canMutate" class="detail-card"><h2>{{ editing ? '编辑需求' : '提出需求' }}</h2><form class="wizard-form" @submit.prevent="editing ? saveRequirement() : create()"><label>标题<input v-model="input.title" required maxlength="255"></label><label>目标<textarea v-model="input.goal" /></label><label>业务场景<textarea v-model="input.scenario" /></label><label>需求链接<input v-model="input.requirement_url" type="url" maxlength="1024"></label><label>期望日期<input v-model="input.due_date" type="date"></label><button class="primary-button" :disabled="busy">{{ editing ? '保存修改' : '创建需求' }}</button><button v-if="editing" type="button" @click="editing=false; input={title:'',goal:'',scenario:'',requirement_url:'',due_date:''}">取消编辑</button></form></article>
<article v-if="selected" class="detail-card detail-card--wide"><h2>{{ selected.title }}</h2><button v-if="projects.canMutate" type="button" @click="editRequirement">编辑需求</button><p>目标：{{ selected.goal || '未填写' }}</p><p>场景：{{ selected.scenario || '未填写' }}</p><p>提出人 ID：{{ selected.created_by }} · 期望日期：{{ selected.due_date || '未填写' }}</p><p v-if="selected.requirement_url"><a :href="selected.requirement_url" target="_blank" rel="noreferrer">需求文档</a></p><h3>接入任务</h3><p v-if="!tasks.length">暂无任务</p><table v-else><thead><tr><th>点位</th><th>平台</th><th>负责人</th><th>进度</th><th>验收</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id"><td>{{ t.point_name }}</td><td>{{ t.platform }}</td><td><select v-if="projects.canMutate" :value="t.assignee_id ?? ''" @change="update(t, t.state, Number(($event.target as HTMLSelectElement).value) || null)"><option value="">未分配</option><option v-for="m in members" :key="m.user_id" :value="m.user_id">{{ m.display_name || m.username }}</option></select><span v-else>{{ members.find(m=>m.user_id===t.assignee_id)?.display_name || members.find(m=>m.user_id===t.assignee_id)?.username || '未分配' }}</span></td><td><select v-if="projects.canMutate" :value="t.state" @change="update(t, ($event.target as HTMLSelectElement).value as TaskInput['state'])"><option value="PENDING">待开发</option><option value="DEVELOPING">开发中</option><option value="TESTING">测试中</option><option value="ONLINE">已上线</option></select><span v-else>{{ t.state }}</span></td><td><TaskAcceptance :project-id="projectId" :requirement-id="selected.id" :task-id="t.id" :can-mutate="projects.canMutate" /><button v-if="projects.canMutate" type="button" @click="removeTask(t)">删除任务</button></td></tr></tbody></table>
<form v-if="projects.canMutate" class="wizard-form" @submit.prevent="addTask"><h3>添加接入任务</h3><label>点位<select v-model.number="task.point_id" required @change="pointChanged"><option :value="0" disabled>请选择</option><option v-for="p in points" :key="p.id" :value="p.id">{{ p.name }}（{{ p.code }}）</option></select></label><label>平台<select v-model="task.platform"><option v-for="p in platforms" :key="p" :value="p">{{ p }}</option></select></label><label>负责人<select v-model="task.assignee_id"><option :value="null">未分配</option><option v-for="m in members" :key="m.user_id" :value="m.user_id">{{ m.display_name || m.username }}</option></select></label><button class="primary-button" :disabled="busy || !task.point_id || !platforms.length">添加任务</button></form></article></div></section>
</template>
